+  // be at least `this->length()` bytes.
+  void copyTo(uint8_t* dest) const {
+    memcpy(dest + envOffset(), env_.data(), env_.size());
+    memcpy(dest + codeOffset(), code_.data(), code_.size());
+    memcpy(dest + tailOffset(), tail_.data(), tail_.size());
