+  // buffers.
+  BytecodeBuffer(const BytecodeBuffer&) = default;
+  BytecodeBuffer& operator=(const BytecodeBuffer&) = default;
+  BytecodeBuffer(BytecodeBuffer&&) = default;
+  BytecodeBuffer& operator=(BytecodeBuffer&&) = default;
